<?php
defined('_JEXEC') or die;
use Joomla\CMS\Language\Text;
$badge = static function (bool $ok): string { $class = $ok ? 'bg-success' : 'bg-warning text-dark'; $label = $ok ? Text::_('JYES') : Text::_('JNO'); return '<span class="badge ' . $class . '">' . htmlspecialchars($label, ENT_QUOTES, 'UTF-8') . '</span>'; };
?>
