      <dt class="col-sm-5"><?php echo Text::_('COM_XDECARONOTIFICATIONS_INFO_NAME'); ?></dt><dd class="col-sm-7"><?php echo htmlspecialchars((string) ($this->product['name'] ?? ''), ENT_QUOTES, 'UTF-8'); ?></dd>
