      <dt class="col-sm-5"><?php echo Text::_('COM_XDECARONOTIFICATIONS_INFO_INSTALLED'); ?></dt><dd class="col-sm-7"><?php echo $badge((bool) ($this->product['installed'] ?? false)); ?></dd>
