      <dt class="col-sm-5"><?php echo Text::_('COM_XDECARONOTIFICATIONS_INFO_DATABASE'); ?></dt><dd class="col-sm-7"><?php echo htmlspecialchars((string) ($this->environment['database'] ?? ''), ENT_QUOTES, 'UTF-8'); ?></dd>
    </dl></div></div></div>
